parameters.jsCode:
const data = $input.all()[0].json;

// 1. ดึงข้อมูลประเภทการลา (ถ้าไม่มีให้เป็น object ว่าง {})
const byLeaveType = data?.byLeaveType || data?.byType || {};
const pieLabels = Object.keys(byLeaveType);
const pieDataValues = Object.values(byLeaveType);

const pieChartConfig = {
  type: 'pie',
  data: {
    labels: pieLabels.length > 0 ? pieLabels : ['ไม่มีข้อมูลการลา'],
    datasets: [{
      data: pieDataValues.length > 0 ? pieDataValues : [1],
      backgroundColor: pieLabels.length > 0 
        ? ['#FF6384', '#36A2EB', '#FFCE56', '#4BC0C0', '#9966FF'] 
        : ['#CBD5E1']
    }]
  },
  options: {
    title: {
      display: true,
      text: 'สัดส่วนประเภทการลา'
    }
  }
};

const pieChartUrl = "https://quickchart.io/chart?c=" + encodeURIComponent(JSON.stringify(pieChartConfig));

// 2. ดึงข้อมูลแผนก (ถ้าไม่มีให้เป็น object ว่าง {})
const byDepartment = data?.byDepartment || {};
const barLabels = Object.keys(byDepartment);
const barDataValues = Object.values(byDepartment);

const barChartConfig = {
  type: 'bar',
  data: {
    labels: barLabels.length > 0 ? barLabels : ['ไม่มีข้อมูล'],
    datasets: [{
      label: 'คำขอลาตามแผนก (รายการ)',
      data: barDataValues.length > 0 ? barDataValues : [0],
      backgroundColor: '#36A2EB'
    }]
  },
  options: {
    title: {
      display: true,
      text: 'สถิติการลาแยกตามแผนก'
    }
  }
};

const barChartUrl = "https://quickchart.io/chart?c=" + encodeURIComponent(JSON.stringify(barChartConfig));

return {
  json: {
    ...data,
    pieChartUrl,
    barChartUrl
  }
};

